"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[7995],{32337(t){t.exports=JSON.parse('{"tag":{"label":"bqp","permalink":"/azeon/p-vs-np/tags/bqp","allTagsPath":"/azeon/p-vs-np/tags","count":3,"items":[{"id":"complexity-zoo/quantum-computing-and-bqp","title":"Quantum Computing and BQP","description":"A quantum computer is not a computer that tries every answer at once. It\'s a computer whose possibilities can cancel each other out. That one idea, interference, is what defines the class BQP.","permalink":"/azeon/p-vs-np/complexity-zoo/quantum-computing-and-bqp"},{"id":"complexity-zoo/shors-algorithm","title":"Shor\'s Algorithm","description":"How a quantum computer would factor huge numbers in polynomial time. Most of the algorithm is ordinary arithmetic you can do by hand. The quantum part is exactly one step: finding when a repeating pattern starts over.","permalink":"/azeon/p-vs-np/complexity-zoo/shors-algorithm"},{"id":"complexity-zoo/will-quantum-computers-solve-np","title":"Will Quantum Computers Solve NP?","description":"Probably not. There\'s a quantum algorithm that speeds up brute-force search, and a theorem that says, in an important sense, it\'s the best possible. A square root of exponential is still exponential.","permalink":"/azeon/p-vs-np/complexity-zoo/will-quantum-computers-solve-np"}],"unlisted":false}}')}}]);